import React from 'react';

import { createDataTestId } from 'utils/test/createDataTestId';

import {
  StyledCard,
  StyledCardHeader,
  StyledCardHeaderLeft,
  StyledCardSubItem,
  StyledCardSubItems,
  StyledContainer,
  StyledContent,
  StyledDivider,
  StyledFlag,
  StyledGrid,
  StyledIconWrapper,
  StyledItemDescription,
  StyledItemHeader,
  StyledItemPage,
  StyledItemTitle,
  StyledStacked,
  StyledStackedItem,
  StyledStackedSubItem,
  StyledStackedSubItemLabel,
  StyledStackedSubItems,
  StyledSubItemLabel,
  StyledTitle,
} from './TableOfContents.styles';

export interface TocSubItem {
  label: string;
  page: number;
  slideId?: string;
  countryImageUrl?: string;
  countryName?: string;
  countryCode?: string;
}

export interface TocItem {
  title: string;
  description?: string;
  page: number;
  icon?: React.ReactNode;
  countryImageUrl?: string;
  countryCode?: string;
  countryName?: string;
  subItems?: TocSubItem[];
  slideId?: string;
}

export type TocGroupLayout = 'stacked' | 'grid';

export interface TocGroup {
  layout?: TocGroupLayout;
  columns?: number;
  items: TocItem[];
}

export interface TableOfContentsProps {
  title?: string;
  cardHeader?: React.ReactNode;
  groups: TocGroup[];
  onItemClick?: (slideId: string) => void;
  dataTestId?: string;
}

export const TableOfContents: React.FC<TableOfContentsProps> = ({
  title = 'Table of Contents',
  cardHeader,
  groups,
  onItemClick,
  dataTestId,
}) => {
  const renderFlag = (item: TocItem, idPrefix: string) => {
    const flagImageUrl = item.countryImageUrl || '';
    if (!flagImageUrl) return null;
    return (
      <StyledFlag
        src={flagImageUrl}
        alt={`${item.countryName ?? item.countryCode ?? 'Country'} flag`}
        data-testid={createDataTestId(dataTestId, `${idPrefix}-flag`)}
      />
    );
  };

  const renderIcon = (item: TocItem, idPrefix: string) => {
    if (!item.icon) return null;
    return (
      <StyledIconWrapper
        data-testid={createDataTestId(dataTestId, `${idPrefix}-icon`)}
      >
        {item.icon}
      </StyledIconWrapper>
    );
  };

  const renderSubItemFlag = (sub: TocSubItem, subId: string) => {
    if (!sub.countryImageUrl) return null;
    return (
      <StyledFlag
        src={sub.countryImageUrl}
        alt={`${sub.countryName ?? sub.countryCode ?? 'Country'} flag`}
        data-testid={createDataTestId(dataTestId, `${subId}-flag`)}
      />
    );
  };

  const handleClick = (slideId?: string) => {
    if (slideId && onItemClick) onItemClick(slideId);
  };

  const renderStackedItem = (item: TocItem, groupIdx: number, idx: number) => {
    const idPrefix = `stacked-${groupIdx}-${idx}`;
    const subItems = item.subItems ?? [];

    return (
      <React.Fragment key={idPrefix}>
        <StyledStackedItem
          data-testid={createDataTestId(dataTestId, idPrefix)}
          onClick={() => handleClick(item.slideId)}
          style={{
            cursor: item.slideId && onItemClick ? 'pointer' : undefined,
          }}
        >
          <StyledItemHeader>
            {renderIcon(item, idPrefix)}
            {renderFlag(item, idPrefix)}
            <StyledItemTitle
              data-testid={createDataTestId(dataTestId, `${idPrefix}-title`)}
            >
              {item.title}
            </StyledItemTitle>
            {item.description && (
              <StyledItemDescription
                data-testid={createDataTestId(
                  dataTestId,
                  `${idPrefix}-description`,
                )}
              >
                {item.description}
              </StyledItemDescription>
            )}
          </StyledItemHeader>
          <StyledItemPage
            data-testid={createDataTestId(dataTestId, `${idPrefix}-page`)}
          >
            {item.page}
          </StyledItemPage>
        </StyledStackedItem>

        {subItems.length > 0 && (
          <StyledStackedSubItems>
            {subItems.map((sub, subIdx) => {
              const subId = `${idPrefix}-sub-${subIdx}`;
              return (
                <StyledStackedSubItem
                  key={subId}
                  data-testid={createDataTestId(dataTestId, subId)}
                  onClick={(e) => {
                    if (sub.slideId) {
                      e.stopPropagation();
                      handleClick(sub.slideId);
                    }
                  }}
                  style={{
                    cursor: sub.slideId && onItemClick ? 'pointer' : undefined,
                  }}
                >
                  <StyledStackedSubItemLabel>
                    {renderSubItemFlag(sub, subId)}
                    <span
                      data-testid={createDataTestId(
                        dataTestId,
                        `${subId}-label`,
                      )}
                    >
                      {sub.label}
                    </span>
                  </StyledStackedSubItemLabel>
                  <StyledItemPage
                    data-testid={createDataTestId(dataTestId, `${subId}-page`)}
                  >
                    {sub.page}
                  </StyledItemPage>
                </StyledStackedSubItem>
              );
            })}
          </StyledStackedSubItems>
        )}
      </React.Fragment>
    );
  };

  const renderGridCard = (item: TocItem, groupIdx: number, idx: number) => {
    const idPrefix = `card-${groupIdx}-${idx}`;
    const subItems = item.subItems ?? [];
    return (
      <StyledCard
        key={idPrefix}
        data-testid={createDataTestId(dataTestId, idPrefix)}
        onClick={() => handleClick(item.slideId)}
        style={{ cursor: item.slideId && onItemClick ? 'pointer' : undefined }}
      >
        <StyledCardHeader>
          <StyledCardHeaderLeft>
            {renderIcon(item, idPrefix)}
            {renderFlag(item, idPrefix)}
            <StyledItemTitle
              data-testid={createDataTestId(dataTestId, `${idPrefix}-title`)}
            >
              {item.title}
            </StyledItemTitle>
          </StyledCardHeaderLeft>
          <StyledItemPage
            data-testid={createDataTestId(dataTestId, `${idPrefix}-page`)}
          >
            {item.page}
          </StyledItemPage>
        </StyledCardHeader>
        <StyledDivider />
        <StyledCardSubItems>
          {subItems.map((sub, subIdx) => {
            const subId = `${idPrefix}-sub-${subIdx}`;
            return (
              <StyledCardSubItem
                key={subId}
                data-testid={createDataTestId(dataTestId, subId)}
                onClick={(e: React.MouseEvent) => {
                  if (sub.slideId) {
                    e.stopPropagation();
                    handleClick(sub.slideId);
                  }
                }}
                style={{
                  cursor: sub.slideId && onItemClick ? 'pointer' : undefined,
                }}
              >
                <StyledSubItemLabel
                  data-testid={createDataTestId(dataTestId, `${subId}-label`)}
                >
                  {sub.label}
                </StyledSubItemLabel>
                <StyledItemPage
                  data-testid={createDataTestId(dataTestId, `${subId}-page`)}
                >
                  {sub.page}
                </StyledItemPage>
              </StyledCardSubItem>
            );
          })}
        </StyledCardSubItems>
      </StyledCard>
    );
  };

  const renderGroup = (group: TocGroup, groupIdx: number) => {
    const layout: TocGroupLayout = group.layout ?? 'stacked';

    if (layout === 'grid') {
      const columns = group.columns ?? 4;
      return (
        <StyledGrid
          key={`group-${groupIdx}`}
          style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }}
          data-testid={createDataTestId(dataTestId, `group-grid-${groupIdx}`)}
        >
          {group.items.map((item, idx) => renderGridCard(item, groupIdx, idx))}
        </StyledGrid>
      );
    }

    return (
      <StyledStacked
        key={`group-${groupIdx}`}
        data-testid={createDataTestId(dataTestId, `group-stacked-${groupIdx}`)}
      >
        {cardHeader && (
          <>
            <StyledCardHeader>{cardHeader}</StyledCardHeader>
            <StyledDivider />
          </>
        )}
        {group.items.map((item, idx) => renderStackedItem(item, groupIdx, idx))}
      </StyledStacked>
    );
  };

  return (
    <StyledContainer data-testid={dataTestId}>
      <StyledContent>
        <StyledTitle data-testid={createDataTestId(dataTestId, 'title')}>
          {title}
        </StyledTitle>
        {groups.map((group, groupIdx) => renderGroup(group, groupIdx))}
      </StyledContent>
    </StyledContainer>
  );
};
